// src/pages/HomePage.jsx
// Senior UI/UX Redesign - Premium, Dynamic & Minimal Style (Canyon & Apple Vibe)
// Ten: Le Thanh Ho | MSSV: 2123110125 | Lop: CCQ2311D

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { 
  ArrowRight, 
  ChevronLeft, 
  ChevronRight, 
  Sparkles, 
  TrendingUp, 
  Flame, 
  MessageSquare, 
  Newspaper, 
  Bike 
} from "lucide-react";

import productService from "../services/productService";
import categoryService from "../services/categoryService";
import postService from "../services/postService";
import reviewService from "../services/reviewService";
import bannerService from "../services/bannerService";
import ProductCard from "../components/ProductCard";
import Loader from "../components/Loader";
import { resolveImageUrl } from "../components/ProductCard";

// 🎯 1. COMPONENT: BANNER SLIDER (DỰA TRÊN 100% LOGIC CŨ - CHỈ REFACTOR UI/UX)
function BannerSlider({ banners, loadingBanners }) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (banners.length <= 1) return;
    const timer = setInterval(() => {
      setIndex((i) => (i + 1) % banners.length);
    }, 6000);
    return () => clearInterval(timer);
  }, [banners]);

  if (loadingBanners) {
    return (
      <div className="h-[550px] bg-[#0F172A] flex items-center justify-center text-white/40">
        <Loader small />
      </div>
    );
  }

  if (banners.length === 0) {
    return (
      <section className="relative bg-[#0F172A] text-white py-24 text-center overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,rgba(201,255,61,0.08),transparent)]" />
        <h1 className="font-display text-4xl font-extrabold tracking-tight">BIKESHOP PRESTIGE</h1>
      </section>
    );
  }

  const slide = banners[index];

  return (
    <section className="relative bg-[#0F172A] text-white h-[520px] md:h-[620px] flex items-center overflow-hidden">
      {/* Dynamic Background Image Image Link Container */}
      <AnimatePresence mode="wait">
        <motion.div
          key={index}
          initial={{ opacity: 0, scale: 1.03 }}
          animate={{ opacity: 0.35, scale: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.8, ease: "easeOut" }}
          className="absolute inset-0 z-0"
        >
          <img
            src={resolveImageUrl(slide.image)}
            alt={slide.title}
            className="w-full h-full object-cover"
          />
        </motion.div>
      </AnimatePresence>

      {/* Premium Gradient Overlay overlay */}
      <div className="absolute inset-0 bg-gradient-to-r from-[#0F172A] via-[#0F172A]/80 to-transparent z-10" />

      {/* High-Tech Grid Decoration decoration */}
      <div 
        className="absolute inset-0 opacity-[0.03] z-10 pointer-events-none"
        style={{ backgroundImage: "repeating-linear-gradient(115deg, transparent, transparent 50px, #C9FF3D 50px, #C9FF3D 52px)" }}
      />

      <div className="max-w-7xl mx-auto px-6 md:px-8 w-full relative z-20">
        <div className="max-w-2xl">
          <motion.div 
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="inline-flex items-center gap-2 bg-white/5 border border-white/10 px-3 py-1.5 rounded-full text-xs font-medium text-[#C9FF3D] uppercase tracking-widest mb-6"
          >
            <Sparkles className="w-3.5 h-3.5" /> Premium Release 2026
          </motion.div>

          <motion.h1 
            key={`title-${index}`}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.1 }}
            className="font-sans font-extrabold text-4xl md:text-6xl tracking-tight leading-[1.1] text-white"
          >
            {slide.title}
          </motion.h1>

          {slide.link && (
            <motion.div
              initial={{ opacity: 0, y: 15 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: 0.3 }}
              className="mt-10"
            >
              <Link
                to={slide.link}
                className="inline-flex items-center gap-2 bg-[#C9FF3D] text-[#0F172A] font-bold px-8 py-4 rounded-xl hover:bg-[#b5e630] transition-all duration-300 shadow-lg shadow-[#C9FF3D]/10 active:scale-95 group"
              >
                Khám phá bộ sưu tập 
                <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-1" />
              </Link>
            </motion.div>
          )}
        </div>

        {/* Premium Indicators - Trình điều hướng Slider tinh giản */}
        {banners.length > 1 && (
          <div className="flex gap-2.5 mt-16 relative z-30">
            {banners.map((_, i) => (
              <button
                key={i}
                onClick={() => setIndex(i)}
                className={`h-1.5 rounded-full transition-all duration-300 ${
                  i === index ? "bg-[#C9FF3D] w-10" : "bg-white/20 w-5 hover:bg-white/40"
                }`}
                aria-label={`Go to slide ${i + 1}`}
              />
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

// 🎯 2. MAIN COMPONENT: HOMEPAGE (CHỈ REFACTOR UI/UX, GIỮ NGUYÊN HOÀN TOÀN DATA & PROMISE LOGIC)
export default function HomePage() {
  const [banners, setBanners] = useState([]);
  const [featured, setFeatured] = useState([]);
  const [bestSellers, setBestSellers] = useState([]);
  const [newest, setNewest] = useState([]);
  const [categories, setCategories] = useState([]);
  const [posts, setPosts] = useState([]);
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingBanners, setLoadingBanners] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        // GIỮ NGUYÊN LUỒNG PROMISE BẤT ĐỒNG BỘ CỦA HỒ ĐỂ ĐẢM BẢO TỐC ĐỘ 
        const [f, b, n, c, p, t, bn] = await Promise.all([
          productService.getFeatured(),
          productService.getBestSellers(),
          productService.getNewest(),
          categoryService.getAll(),
          postService.getPublished(),
          reviewService.getTestimonials(),
          bannerService.getActive(),
        ]);
        setFeatured(f.data);
        setBestSellers(b.data);
        setNewest(n.data);
        setCategories(c.data);
        setPosts(p.data.slice(0, 3));
        setTestimonials(t.data);
        setBanners(bn.data);
      } catch (err) {
        console.error("Lỗi fetch API trang chủ:", err);
      } finally {
        setLoading(false);
        setLoadingBanners(false);
      }
    };
    load();
  }, []);

  return (
    <div className="bg-[#F8FAFC] min-h-screen font-sans antialiased">
      {/* 1. SECTION BANNER SLIDER SLIDER */}
      <BannerSlider banners={banners} loadingBanners={loadingBanners} />

      {/* 2. SECTION CATEGORIES - Phong cách nhãn mác Minimalist */}
      <section className="max-w-7xl mx-auto px-6 md:px-8 py-16">
        <div className="flex items-center gap-2 mb-8">
          <div className="w-1.5 h-6 bg-[#0F172A] rounded-full" />
          <h2 className="font-sans font-extrabold text-2xl tracking-tight text-[#0F172A]">Danh mục xe chuyên dụng</h2>
        </div>

        {loading ? (
          <Loader small />
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
            {categories.map((cat) => (
              <Link
                key={cat.id}
                to={`/products?categoryId=${cat.id}`}
                className="group relative bg-white border border-gray-200/60 rounded-2xl p-6 text-center hover:border-[#0F172A] transition-all duration-300 hover:shadow-[0_10px_30px_rgba(0,0,0,0.03)] hover:-translate-y-1 overflow-hidden"
              >
                <div className="absolute -right-4 -bottom-4 opacity-[0.03] text-[#0F172A] group-hover:scale-110 transition-transform duration-300">
                  <Bike className="w-24 h-24" />
                </div>
                <p className="font-bold text-[#0F172A] text-sm group-hover:text-blue-600 transition-colors">{cat.name}</p>
                <span className="inline-block mt-2 text-[11px] text-gray-400 font-medium bg-gray-50 px-2.5 py-0.5 rounded-full border border-gray-100">
                  Explore Models
                </span>
              </Link>
            ))}
          </div>
        )}
      </section>

      {/* 3. SECTION FEATURED PRODUCTS - Lưới sản phẩm cao cấp */}
      <section className="max-w-7xl mx-auto px-6 md:px-8 py-12">
        <div className="flex items-end justify-between border-b border-gray-200/50 pb-5 mb-8">
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-6 bg-[#0F172A] rounded-full" />
            <h2 className="font-sans font-extrabold text-2xl tracking-tight text-[#0F172A] flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-amber-500" /> Sản phẩm nổi bật
            </h2>
          </div>
          <Link to="/products" className="group text-sm font-bold text-blue-600 hover:text-[#0F172A] flex items-center gap-1 transition-colors">
            Xem tất cả <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-0.5" />
          </Link>
        </div>

        {loading ? (
          <Loader />
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {featured.map((p) => (
              <div key={p.id} className="hover:-translate-y-1.5 transition-transform duration-300">
                <ProductCard product={p} />
              </div>
            ))}
          </div>
        )}
      </section>

      {/* 4. SECTION BEST SELLERS - Biểu tượng Thịnh hành */}
      <section className="max-w-7xl mx-auto px-6 md:px-8 py-12">
        <div className="flex items-end justify-between border-b border-gray-200/50 pb-5 mb-8">
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-6 bg-[#0F172A] rounded-full" />
            <h2 className="font-sans font-extrabold text-2xl tracking-tight text-[#0F172A] flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-blue-600" /> Dòng xe bán chạy nhất
            </h2>
          </div>
          <Link to="/products" className="group text-sm font-bold text-blue-600 hover:text-[#0F172A] flex items-center gap-1 transition-colors">
            Xem tất cả <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-0.5" />
          </Link>
        </div>

        {loading ? (
          <Loader />
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {bestSellers.map((p) => (
              <div key={p.id} className="hover:-translate-y-1.5 transition-transform duration-300">
                <ProductCard product={p} />
              </div>
            ))}
          </div>
        )}
      </section>

      {/* 5. SECTION NEWEST PRODUCTS - Đón đầu xu hướng */}
      <section className="max-w-7xl mx-auto px-6 md:px-8 py-12">
        <div className="flex items-center gap-2 border-b border-gray-200/50 pb-5 mb-8">
          <div className="w-1.5 h-6 bg-[#0F172A] rounded-full" />
          <h2 className="font-sans font-extrabold text-2xl tracking-tight text-[#0F172A] flex items-center gap-2">
            <Flame className="w-5 h-5 text-red-500" /> Bộ sưu tập xe mới về
          </h2>
        </div>

        {loading ? (
          <Loader />
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {newest.map((p) => (
              <div key={p.id} className="hover:-translate-y-1.5 transition-transform duration-300">
                <ProductCard product={p} />
              </div>
            ))}
          </div>
        )}
      </section>

      {/* 6. SECTION TESTIMONIALS - Đánh giá từ cộng đồng Rider */}
      {!loading && testimonials.length > 0 && (
        <section className="bg-white border-y border-gray-200/40 py-20 mt-12 shadow-[inset_0_2px_4px_rgba(0,0,0,0.01)] relative overflow-hidden">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_bottom_left,rgba(59,130,246,0.02),transparent)]" />
          <div className="max-w-7xl mx-auto px-6 md:px-8 relative z-10">
            <div className="flex items-center gap-2 mb-10">
              <MessageSquare className="w-5 h-5 text-blue-500" />
              <h2 className="font-sans font-extrabold text-2xl tracking-tight text-[#0F172A]">
                Cộng đồng Rider nói gì về BikeShop
              </h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {testimonials.slice(0, 3).map((r) => (
                <div key={r.id} className="bg-[#F8FAFC]/60 backdrop-blur-sm border border-gray-200/60 rounded-2xl p-6 shadow-sm hover:border-gray-300 transition duration-300">
                  <div className="flex text-amber-400 gap-0.5 text-xs mb-4">
                    {"★".repeat(r.rating)}
                    <span className="text-gray-200">{"★".repeat(5 - r.rating)}</span>
                  </div>
                  <p className="text-sm text-gray-600 italic leading-relaxed mb-6">"{r.comment}"</p>
                  <div className="border-t border-gray-200/40 pt-4 mt-auto">
                    <p className="text-xs font-bold text-[#0F172A]">{r.userFullname}</p>
                    <p className="text-[11px] text-blue-600 font-semibold mt-0.5 truncate">{r.productName}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* 7. SECTION LATEST POSTS - Cẩm nang tạp chí thể thao */}
      {!loading && posts.length > 0 && (
        <section className="max-w-7xl mx-auto px-6 md:px-8 py-20">
          <div className="flex items-end justify-between border-b border-gray-200/50 pb-5 mb-10">
            <div className="flex items-center gap-2">
              <Newspaper className="w-5 h-5 text-[#0F172A]" />
              <h2 className="font-sans font-extrabold text-2xl tracking-tight text-[#0F172A]">
                Tạp chí xe & Cẩm nang đường trường
              </h2>
            </div>
            <Link to="/posts" className="group text-sm font-bold text-blue-600 hover:text-[#0F172A] flex items-center gap-1 transition-colors">
              Xem tất cả bài viết <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-0.5" />
            </Link>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {posts.map((post) => (
              <Link
                key={post.id}
                to={`/posts/${post.slug}`}
                className="group block bg-white border border-gray-200/60 rounded-2xl overflow-hidden hover:shadow-xl hover:border-gray-300 transition-all duration-300"
              >
                <div className="aspect-[16/10] bg-gray-50 overflow-hidden relative">
                  <img
                    src={resolveImageUrl(post.thumbnail) || "https://placehold.co/400x225?text=BikeShop"}
                    alt={post.title}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                  />
                  <div className="absolute top-4 left-4 bg-[#0F172A] text-white text-[10px] font-bold uppercase tracking-widest px-2.5 py-1 rounded-md shadow-sm">
                    {new Date(post.createdAt).toLocaleDateString("vi-VN", { month: "short", day: "numeric" })}
                  </div>
                </div>
                <div className="p-5">
                  <h3 className="font-bold text-[#0F172A] text-base group-hover:text-blue-600 transition-colors line-clamp-2 leading-snug">
                    {post.title}
                  </h3>
                  <p className="text-xs text-gray-400 font-medium mt-3 flex items-center gap-1.5">
                    Read Journal <ArrowRight className="w-3 h-3 group-hover:translate-x-1 transition-transform" />
                  </p>
                </div>
              </Link>
            ))}
          </div>
        </section>
      )}
    </div>
  );
}
